-- Re-runnable seed script: clears only these three tables, then reloads source CSV rows.
-- Run after schema.sql: sqlite3 mamaearth.db < sql/seed_data.sql
PRAGMA foreign_keys = ON;
BEGIN TRANSACTION;
DELETE FROM orders;
DELETE FROM products;
DELETE FROM customers;

-- Load 45 raw rows into customers (customer_id, customer_name, city, city_tier, signup_date, acquisition_source).

-- Load 16 raw rows into products (product_id, product_name, category, price).

-- Load 180 raw rows into orders (order_id, customer_id, product_id, order_date, quantity, discount_pct, payment_method, rating, is_returned).
COMMIT;

-- Expected raw counts: customers=45, products=16, orders=180.
SELECT 'customers' AS table_name, COUNT(*) AS row_count FROM customers
UNION ALL SELECT 'products', COUNT(*) FROM products
UNION ALL SELECT 'orders', COUNT(*) FROM orders;
